// Nearest-neighbour matching on a scalar score without replacement, after the Matching package's Match(Tr, X,
// estimand, M, caliper, ties = FALSE, replace = FALSE): the behaviour and the choices are in oracle/match-behaviour.md.
// Written for rStats.js from the package's documentation and its published output (no ported code).
import { unifRand } from "../random/rng.js";
import { ldexp } from "../internal/summary.js";
import { rescaled } from "./scale.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const MATCH_KEYS = ["estimand", "M", "caliper"];
/**
 * Nearest-neighbour matching on a scalar score, without replacement and with random tie-breaking. Equivalent to
 * `Matching::Match()` in R. The call followed is
 * `Match(Tr = tr, X = x, estimand, M, caliper, ties = FALSE, replace = FALSE)`, used with the linear predictor
 * `logit(PS)` of a propensity score model.
 *
 * The matched units (the treated for ATT, the controls for ATC, all for ATE) are processed in data order. Each takes
 * its matches from the units of the other group not yet used: every available unit within the M-th smallest distance
 * is a candidate (within the caliper when one is given), and when there are more candidates than M, M of them are
 * drawn at random. A unit with fewer than M available candidates is dropped. Pairs are listed in the order of the
 * matched units, the controls of one treated unit (ATT) in row order.
 *
 * Random draws use rStats.js's generator (`setSeed`): one uniform `u` for each pick, and the candidate at 0-based
 * index `floor(k (1 - u))` among the `k` remaining (in row order) is taken. Without ties no random number is used and
 * the pairs are R's; with sets of two candidates the rule is R's (the second when `u < 0.5`). Known differences from
 * R: larger tie sets are broken differently (R's rule is not documented), and distances count as tied only when
 * exactly equal (R also treats distances within `distance.tolerance = 1e-5` as ties). `M` below 1 is an error (R
 * warns and uses 1).
 * @category Causal inference
 * @example
 * ```ts
 * const m = match([1, 0, 1, 0, 0], [0.2, 0.1, 1.5, 1.4, 3]);
 * m.indexTreated; // [1, 3]
 * m.indexControl; // [2, 4]
 * ```
 */
export function match(tr, x, options = {}) {
    checkOptions(options, MATCH_KEYS, "match"); // generated: option-keys.mjs
    const { estimand = "ATT", M = 1, caliper } = options;
    const n = tr.length;
    if (x.length !== n)
        throw new RangeError("length(Tr) != nrow(X)");
    if (estimand !== "ATT" && estimand !== "ATE" && estimand !== "ATC")
        throw new RangeError(`invalid 'estimand': ${String(estimand)}`);
    if (!Number.isInteger(M) || M < 1)
        throw new RangeError("'M' must be a positive integer");
    if (caliper !== undefined && !(caliper > 0 && Number.isFinite(caliper)))
        throw new RangeError("'caliper' must be a positive number");
    const treated = [];
    for (let i = 0; i < n; i++) {
        const t = tr[i];
        if (t === true || t === 1)
            treated.push(true);
        else if (t === false || t === 0)
            treated.push(false);
        else if (typeof t === "number" && Number.isNaN(t))
            throw new RangeError("Match(): input includes NAs");
        else
            throw new RangeError("Treatment indicator ('Tr') must be a logical variable---i.e., TRUE (1) or FALSE (0)");
        if (!Number.isFinite(x[i]))
            throw new RangeError("Match(): input includes NAs");
    }
    if (!treated.includes(true) || !treated.includes(false)) {
        throw new RangeError("Treatment indicator ('Tr') must contain both treatment and control observations");
    }
    // distances and the caliper in units of 2^e, the power of 2 of the largest |x|: exact (the ties stay ties), and
    // neither overflowing for |x| near 1e308 nor underflowing for |x| near 1e-300
    let top = 0;
    for (const v of x)
        top = Math.max(top, Math.abs(v));
    const unitExp = top > 0 ? Math.floor(Math.log2(top)) : 0;
    const xs = x.map((v) => ldexp(v, -unitExp));
    let ecaliper = null;
    let reach = Infinity; // the caliper in the units of xs
    if (caliper !== undefined) {
        // the SD with divisor n, from the column rescaled exactly (and shifted: a large common offset keeps its digits)
        const { values: r, unitExp: rExp } = rescaled(xs);
        let mean = 0;
        for (const v of r)
            mean += v;
        mean /= n;
        let ss = 0;
        for (const v of r)
            ss += (v - mean) * (v - mean);
        const sd = ldexp(Math.sqrt(ss / n), rExp); // in the units of xs
        reach = caliper * sd;
        ecaliper = ldexp(reach, unitExp);
    }
    // separate pools: the controls still available to treated units, the treated still available to controls
    const used = [new Array(n).fill(false), new Array(n).fill(false)]; // [for treated, for controls]
    const indexTreated = [];
    const indexControl = [];
    const dropped = [];
    const tieSizes = [];
    let wnobs = 0;
    let ndrops = 0;
    for (let i = 0; i < n; i++) {
        const isT = treated[i];
        if (isT ? estimand === "ATC" : estimand === "ATT")
            continue;
        const pool = used[isT ? 0 : 1];
        // available units of the other group within the caliper, with their distances
        const cand = [];
        for (let j = 0; j < n; j++) {
            if (treated[j] === isT)
                continue;
            const d = Math.abs(xs[i] - xs[j]);
            if (d > reach)
                continue;
            if (!pool[j])
                cand.push({ j, d });
        }
        if (cand.length < M) {
            ndrops++;
            dropped.push(i + 1);
            continue;
        }
        // the M-th smallest distance; every candidate within it
        const sorted = cand.map((c) => c.d).sort((a, b) => a - b);
        const dM = sorted[M - 1];
        let set = cand.filter((c) => c.d <= dM).map((c) => c.j); // row order
        let chosen;
        if (set.length === M)
            chosen = set;
        else {
            tieSizes.push(set.length);
            chosen = [];
            set = set.slice();
            for (let p = 0; p < M; p++) {
                const k = set.length;
                const idx = Math.min(k - 1, Math.floor(k * (1 - unifRand())));
                chosen.push(set[idx]);
                set.splice(idx, 1);
            }
            chosen.sort((a, b) => a - b);
        }
        for (const j of chosen) {
            pool[j] = true;
            indexTreated.push((isT ? i : j) + 1);
            indexControl.push((isT ? j : i) + 1);
        }
        wnobs++;
    }
    // R lists (with a caliper) the dropped units that appear in no pair: under ATE a dropped unit may still be the match
    // of another unit
    const inPairs = new Set([...indexTreated, ...indexControl]);
    const listed = ecaliper === null ? [] : dropped.filter((r) => !inPairs.has(r));
    const warnings = [];
    if (indexTreated.length === 0) {
        warnings.push("'Match' object contains no valid matches (probably because of the caliper or the exact option).");
    }
    return {
        indexTreated, indexControl, weights: indexTreated.map(() => 1 / M), indexDropped: listed.length > 0 ? listed : null,
        caliper: caliper ?? null, ecaliper, nobs: n, wnobs, ndrops, estimand, M, tieSizes, warnings,
    };
}
